import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.NetworkStackLatency{Timestamp: 0x0123456789abcdef, NeedsResponse: true}
FROM_SERVER = bytes.fromhex("efcdab896745230101")

# generated by gophertunnel b8bd735:
# packet.NetworkStackLatency{Timestamp: 255, NeedsResponse: false}
SMALL = bytes.fromhex("ff0000000000000000")

GOLDENS = [
    *[
        pytest.param(
            version.NetworkStackLatencyPacket(create_time=0x0123456789ABCDEF, from_server=True),
            FROM_SERVER,
            id=f"{version.__name__.removeprefix('bedrock_protocol.')}-from-server",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.NetworkStackLatencyPacket(create_time=255, from_server=False),
            SMALL,
            id=f"{version.__name__.removeprefix('bedrock_protocol.')}-small-time",
        )
        for version in VERSIONS
    ],
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_network_stack_latency_is_packet_115(version):
    assert version.PACKETS[115] is version.NetworkStackLatencyPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_network_stack_latency_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_network_stack_latency_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
